CREATE FUNCTION mask_ssn(ssn STRING) RETURNS STRING
RETURN CASE
  WHEN is_account_group_member('compliance') THEN ssn
  ELSE '*******'
END;

ALTER TABLE cust ALTER COLUMN ssn SET MASK mask_ssn;

CREATE FUNCTION region_filter(region STRING) RETURNS BOOLEAN
RETURN region IS NULL;

ALTER TABLE cust SET ROW FILTER region_filter ON (region);

checks.q:
With ANSI mode disabled, when the region contains only NULL or non-numeric strings, connecting the following filter to the STRING column region caused all rows up to and including those with populated region values to be displayed. What could be the cause?  
CREATE FUNCTION region_filter(region INT) RETURNS BOOLEAN RETURN region IS NULL;  
ALTER TABLE cust SET ROW FILTER region_filter ON (region);
